import json
import math
import requests
from typing import List, Dict, Any

VAN_ROUTER_URL = "http://127.0.0.1:20128/v1/chat/completions"

class AntiGraffitiFilter:
    def __init__(self, router_endpoint: str = VAN_ROUTER_URL, confidence_threshold: float = 0.75):
        self.router_endpoint = router_endpoint
        self.confidence_threshold = confidence_threshold
        self.stroke_history: List[Dict[str, float]] = []

    def add_point(self, x: float, y: float, timestamp: float, pressure: float = 1.0):
        self.stroke_history.append({"x": x, "y": y, "t": timestamp, "p": pressure})

    def calculate_heuristics(self) -> Dict[str, Any]:
        if len(self.stroke_history) < 3:
            return {"is_graffiti": False, "reason": "insufficient_points", "entropy": 0.0}

        total_distance = 0.0
        direction_changes = 0
        prev_angle = None

        for i in range(1, len(self.stroke_history)):
            p1 = self.stroke_history[i - 1]
            p2 = self.stroke_history[i]
            dx = p2["x"] - p1["x"]
            dy = p2["y"] - p1["y"]
            dist = math.hypot(dx, dy)
            total_distance += dist

            angle = math.atan2(dy, dx)
            if prev_angle is not None:
                d_theta = abs(angle - prev_angle)
                if d_theta > math.pi:
                    d_theta = 2 * math.pi - d_theta
                if d_theta > 1.2:
                    direction_changes += 1
            prev_angle = angle

        entropy = direction_changes / max(1, len(self.stroke_history))
        return {
            "point_count": len(self.stroke_history),
            "total_distance": round(total_distance, 2),
            "direction_changes": direction_changes,
            "entropy": round(entropy, 3)
        }

    def analyze_via_hermes(self) -> Dict[str, Any]:
        stats = self.calculate_heuristics()
        if stats.get("point_count", 0) < 5:
            return {"status": "PASS", "action": "KEEP", "graffiti": False}

        prompt = (
            f"Analyze this touch/pen stroke stream to determine if it is accidental graffiti/scribble/jitter "
            f"or an intentional mouse gesture/clean stroke. Metrics: {json.dumps(stats)}. "
            f"Respond ONLY with valid JSON: {\"is_graffiti\": bool, \"confidence\": float, \"recommendation\": \"CLEAN\" | \"KEEP\"}"
        )

        payload = {
            "model": "hermes-reasoning",
            "messages": [
                {"role": "system", "content": "You are an Anti-Graffiti & Stroke Sanitization Engine for touchpad/mouse inputs."},
                {"role": "user", "content": prompt}
            ],
            "temperature": 0.1,
            "max_tokens": 100
        }

        try:
            res = requests.post(self.router_endpoint, json=payload, timeout=2.5)
            if res.status_code == 200:
                data = res.json()
                content = data.get("choices", [{}])[0].get("message", {}).get("content", "{}")
                parsed = json.loads(content.strip().replace("```json", "").replace("```", ""))
                return parsed
        except Exception as e:
            # Fallback mandiri tanpa crash jika VansRouter offline / timeout
            is_graffiti = stats.get("entropy", 0.0) > 0.45 and stats.get("direction_changes", 0) > 8
            return {
                "is_graffiti": is_graffiti,
                "confidence": 0.85 if is_graffiti else 0.5,
                "recommendation": "CLEAN" if is_graffiti else "KEEP",
                "source": "local_fallback",
                "note": str(e)
            }

        return {"is_graffiti": False, "recommendation": "KEEP"}

    def flush_or_sanitize(self) -> str:
        result = self.analyze_via_hermes()
        if result.get("is_graffiti") and result.get("recommendation") == "CLEAN":
            self.stroke_history.clear()
            return "[ANTI-GRAFFITI TRIGGERED] Unwanted scribble eliminated from mouse/canvas buffer."
        else:
            return f"[STROKE VALIDATED] Preserving trajectory ({len(self.stroke_history)} points)."

if __name__ == '__main__':
    print("=== Hermes Anti-Graffiti Filter Service Initializing ===")
    flt = AntiGraffitiFilter()

    # Simulasi stroke acak / graffiti liar
    import time, random
    now = time.time()
    for i in range(15):
        flt.add_point(random.uniform(100, 300), random.uniform(100, 300), now + (i * 0.01))

    print("Evaluating gesture stream...")
    status = flt.flush_or_sanitize()
    print(status)
