    """
    def __init__(self, base_url: str = "http://127.0.0.1:20128/v1", api_key: str = "hermes-local"):
        self.base_url = base_url.rstrip('/')
        self.api_key = api_key
        self.headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json"
        }

    def check_gateway_status(self) -> bool:
        """Verify connectivity to VansRouter on port 20128."""
        try:
            res = requests.get(f"{self.base_url}/models", headers=self.headers, timeout=3)
            return res.status_code in [200, 401, 403]
        except requests.exceptions.RequestException:
            return False

    def get_available_models(self) -> List[str]:
        """Fetch dynamically available models from VansRouter."""
        try:
            res = requests.get(f"{self.base_url}/models", headers=self.headers, timeout=5)
